package main

import "fmt"

type Point struct {
	X, Y int
}

func main() {
	p := Point{X: 3, Y: 4}
	name := "Ada"
	pi := 3.14159

	// General verbs on a struct.
	fmt.Printf("%v\n", p)   // default: {3 4}
	fmt.Printf("%+v\n", p)  // with field names
	fmt.Printf("%#v\n", p)  // Go-syntax representation
	fmt.Printf("%T\n", p)   // the type

	// String vs quoted string.
	fmt.Printf("%s\n", name) // raw string
	fmt.Printf("%q\n", name) // double-quoted, escaped

	// Integer in several bases.
	fmt.Printf("%d %b %o %x %X\n", 255, 255, 255, 255, 255)

	// Float precision and scientific form.
	fmt.Printf("%f\n", pi)    // default 6 decimals
	fmt.Printf("%.2f\n", pi)  // two decimals
	fmt.Printf("%e\n", pi)    // scientific

	// Width, precision, padding, sign, alignment.
	fmt.Printf("|%5d|%-5d|%05d|\n", 42, 42, 42) // right, left, zero-padded
	fmt.Printf("|%8.2f|\n", pi)                   // width 8, 2 decimals
	fmt.Printf("%+d %+d\n", 7, -7)                // explicit sign

	// Explicit argument index reuses the same arg.
	fmt.Printf("%[1]d squared is %[1]d*%[1]d\n", 9)
}

package main

import "fmt"

type Status int

const (
	Pending Status = iota
	Active
	Closed
)

// String makes Status satisfy fmt.Stringer.
func (s Status) String() string {
	switch s {
	case Pending:
		return "PENDING"
	case Active:
		return "ACTIVE"
	case Closed:
		return "CLOSED"
	default:
		return fmt.Sprintf("Status(%d)", int(s))
	}
}

// validationError satisfies the error interface.
type validationError struct {
	Field string
}

func (e *validationError) Error() string {
	return fmt.Sprintf("invalid field: %s", e.Field)
}

func main() {
	s := Active

	fmt.Printf("%v\n", s)        // uses String(): ACTIVE
	fmt.Printf("%s\n", s)        // uses String(): ACTIVE
	fmt.Printf("%d\n", s)        // bypasses String(): 1
	fmt.Println(Pending, Closed) // both via String()

	// String() is used for elements of a slice too.
	all := []Status{Pending, Active, Closed}
	fmt.Printf("%v\n", all)

	// An error value prints via Error() under %v.
	var err error = &validationError{Field: "email"}
	fmt.Printf("%v\n", err)
}

package main

import (
	"bytes"
	"fmt"
	"os"
)

func main() {
	// Sprintf builds a string in memory.
	id, total := 1042, 79.5
	line := fmt.Sprintf("order %d total $%.2f", id, total)
	fmt.Println(line)

	// Fprintf to os.Stderr for diagnostics (goes to stderr, not stdout).
	fmt.Fprintf(os.Stderr, "war: low stock for order %d\n", id)

	// Fprintf to a bytes.Buffer to accumulate output.
	var buf bytes.Buffer
	for i := 1; i <= 3; i++ {
		fmt.Fprintf(&buf, "row %d: %s\n", i, fmt.Sprintf("value-%d", i*10))
	}
	fmt.Print(buf.String())

	// Sscanf parses a formatted string into typed variables.
	var parsedID int
	var parsedTotal float64
	n, err := fmt.Sscanf("order 1042 total $79.50", "order %d total $%f", &parsedID, &parsedTotal)
	fmt.Printf("scanned %d items, err=%v -> id=%d total=%.2f\n", n, err, parsedID, parsedTotal)
}
